package app.conversions

import app.UnitOfWork
import app.application_models.Product as ProductModel
import app.application_models.ProductStatus
import app.dtos.ProductCreate
import app.dtos.ProductRead
import app.errors.NotFoundException

/** Conversions between the application models and the "products" table: what the service takes and returns. */
object ProductConversions {
    /** A Product as the products table takes it. */
    fun productModelToProductCreate(model: ProductModel, uow: UnitOfWork): ProductCreate {
        val category = uow.categories.findByName(model.categoryName)
            ?: throw NotFoundException("Category", model.categoryName)
        return ProductCreate(
            categoryId = category.id,
            name = model.name,
            price = model.price,
            status = when (model.status) { ProductStatus.DRAFT -> "draft"; ProductStatus.LIVE -> "live" },
        )
    }

    /** A row of the products table as a Product. */
    fun productReadToProductModel(row: ProductRead, uow: UnitOfWork): ProductModel {
        val category = uow.categories.findById(row.categoryId)
        return ProductModel().apply {
            id = row.id
            name = row.name
            price = row.price
            status = when (row.status) { "draft" -> ProductStatus.DRAFT; "live" -> ProductStatus.LIVE; else -> throw IllegalArgumentException("No ProductStatus for this value") }
            categoryName = (category?.name)!!
            tagIds = uow.productTags.listByProductId(row.id).map { it.tagId!! }
        }
    }
}

