package app.repositories

import app.common.Page
import app.entities.Category

/** Keeps categories rows in memory, for tests and for trying the services without a database. */
class MemoryCategoryRepository : CategoryRepository {
    private val rows = linkedMapOf<List<Any?>, Category>()
    private var nextId = 1L

    /** The key of a row, as a list of its key values. */
    private fun keyOf(row: Category): List<Any?> = listOf(row.id)

    /** Orders two keys value by value. */
    @Suppress("UNCHECKED_CAST")
    private fun compareKeys(a: List<Any?>, b: List<Any?>): Int {
        for (index in a.indices) {
            val order = compareValues(a[index] as Comparable<Any>?, b[index] as Comparable<Any>?)
            if (order != 0) return order
        }
        return 0
    }

    private fun visible(): List<Category> =
        rows.values.filter { true }.sortedWith { a, b -> compareKeys(keyOf(a), keyOf(b)) }

    override fun findById(id: Int): Category? {
        return visible().firstOrNull { it.id == id }
    }

    override fun list(offset: Int, limit: Int): Page<Category> {
        val rows = visible()
        return Page(rows.drop(offset).take(limit), rows.size.toLong(), offset, limit)
    }

    override fun findByName(name: String): Category? {
        return visible().firstOrNull { it.name == name }
    }

    override fun insert(entity: Category): Category {
        entity.id = entity.id ?: (nextId++).toInt()
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun update(entity: Category): Category {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun delete(entity: Category): Unit {
        rows.remove(keyOf(entity))
    }
}

