package app.repositories

import app.common.Page
import app.entities.Category
import app.entities.CategoryTable
import app.errors.ConflictException
import org.jetbrains.exposed.v1.core.ResultRow
import org.jetbrains.exposed.v1.core.SortOrder
import org.jetbrains.exposed.v1.core.eq
import org.jetbrains.exposed.v1.exceptions.ExposedSQLException
import org.jetbrains.exposed.v1.jdbc.Database
import org.jetbrains.exposed.v1.jdbc.deleteWhere
import org.jetbrains.exposed.v1.jdbc.insert
import org.jetbrains.exposed.v1.jdbc.selectAll
import org.jetbrains.exposed.v1.jdbc.transactions.transaction as exposedTransaction
import org.jetbrains.exposed.v1.jdbc.update

/** Keeps categories rows in the database, through Exposed. Every call joins the transaction already open, or is committed at once. */
class SqlCategoryRepository(private val db: Database) : CategoryRepository {
    override fun findById(id: Int): Category? {
        return exposedTransaction(db) {
            CategoryTable.selectAll().where { CategoryTable.id eq id }.map { toEntity(it) }.singleOrNull()
        }
    }

    override fun list(offset: Int, limit: Int): Page<Category> {
        return exposedTransaction(db) {
            val query = CategoryTable.selectAll()
            val total = query.count()
            val items = query.orderBy(CategoryTable.id to SortOrder.ASC).limit(limit).offset(offset.toLong()).map { toEntity(it) }
            Page(items, total, offset, limit)
        }
    }

    override fun findByName(name: String): Category? {
        return exposedTransaction(db) {
            CategoryTable.selectAll().where { CategoryTable.name eq name }.map { toEntity(it) }.singleOrNull()
        }
    }

    override fun insert(entity: Category): Category {
        return write {
            val statement = CategoryTable.insert { row ->
                entity.name?.let { row[CategoryTable.name] = it }
            }
            entity.id = statement[CategoryTable.id]
            fill(entity, CategoryTable.selectAll().where { CategoryTable.id eq entity.id!! }.single())
            entity
        }
    }

    override fun update(entity: Category): Category {
        return write {
            CategoryTable.update({ CategoryTable.id eq entity.id!! }) { row ->
                entity.name?.let { row[CategoryTable.name] = it }
            }
            entity
        }
    }

    override fun delete(entity: Category): Unit {
        write {
            CategoryTable.deleteWhere { CategoryTable.id eq entity.id!! }
        }
    }

    private fun toEntity(row: ResultRow): Category = Category().also { fill(it, row) }

    private fun fill(entity: Category, row: ResultRow) {
        entity.id = row[CategoryTable.id]
        entity.name = row[CategoryTable.name]
    }

    /** Runs a write in a transaction; a database refusal (a unique value, a row still pointed to) becomes a ConflictException. */
    private fun <T> write(work: () -> T): T =
        try {
            exposedTransaction(db) { work() }
        } catch (error: ExposedSQLException) {
            // SQLSTATE class 23: the change breaks a constraint (SQLite says so in its message)
            if (!error.sqlState.startsWith("23") && error.cause?.message?.contains("SQLITE_CONSTRAINT") != true) throw error
            throw ConflictException("Category", "the database refused the change: ${error.cause?.message}")
        }
}

