import org.jetbrains.exposed.v1.exceptions.ExposedSQLException
import org.jetbrains.exposed.v1.jdbc.Database
import org.jetbrains.exposed.v1.jdbc.deleteWhere
import org.jetbrains.exposed.v1.jdbc.insert
import org.jetbrains.exposed.v1.jdbc.selectAll
import org.jetbrains.exposed.v1.jdbc.transactions.transaction as exposedTransaction

/** Keeps product_tags rows in the database, through Exposed. Every call joins the transaction already open, or is committed at once. */
class SqlProductTagRepository(private val db: Database) : ProductTagRepository {
    override fun findByProductIdAndTagId(productId: Long, tagId: Int): ProductTag? {
        return exposedTransaction(db) {
            ProductTagTable.selectAll().where { (ProductTagTable.productId eq productId) and (ProductTagTable.tagId eq tagId) }.map { toEntity(it) }.singleOrNull()
        }
    }

    override fun list(offset: Int, limit: Int): Page<ProductTag> {
        return exposedTransaction(db) {
            val query = ProductTagTable.selectAll()
            val total = query.count()
            val items = query.orderBy(ProductTagTable.productId to SortOrder.ASC, ProductTagTable.tagId to SortOrder.ASC).limit(limit).offset(offset.toLong()).map { toEntity(it) }
            Page(items, total, offset, limit)
        }
    }

    override fun listByProductId(productId: Long): List<ProductTag> {
        return exposedTransaction(db) {
            ProductTagTable.selectAll().where { ProductTagTable.productId eq productId }.orderBy(ProductTagTable.productId to SortOrder.ASC, ProductTagTable.tagId to SortOrder.ASC).map { toEntity(it) }
        }
    }

    override fun listByTagId(tagId: Int): List<ProductTag> {
        return exposedTransaction(db) {
            ProductTagTable.selectAll().where { ProductTagTable.tagId eq tagId }.orderBy(ProductTagTable.productId to SortOrder.ASC, ProductTagTable.tagId to SortOrder.ASC).map { toEntity(it) }
        }
    }

    override fun insert(entity: ProductTag): ProductTag {
        return write {
            ProductTagTable.insert { row ->
                entity.productId?.let { row[ProductTagTable.productId] = it }
                entity.tagId?.let { row[ProductTagTable.tagId] = it }
            }
            fill(entity, ProductTagTable.selectAll().where { (ProductTagTable.productId eq entity.productId!!) and (ProductTagTable.tagId eq entity.tagId!!) }.single())
            entity
        }
    }

    override fun delete(entity: ProductTag): Unit {
        write {
            ProductTagTable.deleteWhere { (ProductTagTable.productId eq entity.productId!!) and (ProductTagTable.tagId eq entity.tagId!!) }
        }
    }

    private fun toEntity(row: ResultRow): ProductTag = ProductTag().also { fill(it, row) }

    private fun fill(entity: ProductTag, row: ResultRow) {
        entity.productId = row[ProductTagTable.productId]
        entity.tagId = row[ProductTagTable.tagId]
    }

    /** Runs a write in a transaction; a database refusal (a unique value, a row still pointed to) becomes a ConflictException. */
    private fun <T> write(work: () -> T): T =
        try {
            exposedTransaction(db) { work() }
        } catch (error: ExposedSQLException) {
            // SQLSTATE class 23: the change breaks a constraint (SQLite says so in its message)
            if (!error.sqlState.startsWith("23") && error.cause?.message?.contains("SQLITE_CONSTRAINT") != true) throw error
            throw ConflictException("ProductTag", "the database refused the change: ${error.cause?.message}")
        }
}

