/** Keeps tags rows in the database, through Exposed. Every call joins the transaction already open, or is committed at once. */
class SqlTagRepository(private val db: Database) : TagRepository {
    override fun findById(id: Int): Tag? {
        return exposedTransaction(db) {
            TagTable.selectAll().where { TagTable.id eq id }.map { toEntity(it) }.singleOrNull()
        }
    }

    override fun list(offset: Int, limit: Int): Page<Tag> {
        return exposedTransaction(db) {
            val query = TagTable.selectAll()
            val total = query.count()
            val items = query.orderBy(TagTable.id to SortOrder.ASC).limit(limit).offset(offset.toLong()).map { toEntity(it) }
            Page(items, total, offset, limit)
        }
    }

    override fun insert(entity: Tag): Tag {
        return write {
            val statement = TagTable.insert { row ->
                entity.label?.let { row[TagTable.label] = it }
            }
            entity.id = statement[TagTable.id]
            fill(entity, TagTable.selectAll().where { TagTable.id eq entity.id!! }.single())
            entity
        }
    }

    override fun update(entity: Tag): Tag {
        return write {
            TagTable.update({ TagTable.id eq entity.id!! }) { row ->
                entity.label?.let { row[TagTable.label] = it }
            }
            entity
        }
    }

    override fun delete(entity: Tag): Unit {
