            TagTable.deleteWhere { TagTable.id eq entity.id!! }
        }
    }

    private fun toEntity(row: ResultRow): Tag = Tag().also { fill(it, row) }

    private fun fill(entity: Tag, row: ResultRow) {
        entity.id = row[TagTable.id]
