package app

import app.entities.CategoryTable
import app.entities.CustomerTable
import app.entities.ProductTable
import app.entities.ProductTagTable
import app.entities.TagTable
import org.jetbrains.exposed.v1.jdbc.Database
import org.jetbrains.exposed.v1.jdbc.SchemaUtils
import org.jetbrains.exposed.v1.jdbc.transactions.transaction as exposedTransaction

/** The test database: the PostgreSQL database TEST_DATABASE_URL names (with TEST_DATABASE_USER and TEST_DATABASE_PASSWORD), created from the table objects before every test. */
object TestDatabase {
    private val TABLES = arrayOf(CustomerTable, CategoryTable, ProductTable, TagTable, ProductTagTable)

    /** The repositories over the test database, with every table dropped and created again. */
    fun open(): SqlUnitOfWork {
        val url = System.getenv("TEST_DATABASE_URL")
        // The table objects are written for one kind of database: the tests cannot fall back to SQLite
        checkNotNull(url) { "The database tests need a disposable PostgreSQL database: set TEST_DATABASE_URL (it is emptied)" }
        val db = Database.connect(url, user = System.getenv("TEST_DATABASE_USER") ?: "", password = System.getenv("TEST_DATABASE_PASSWORD") ?: "")
        exposedTransaction(db) {
            SchemaUtils.drop(*TABLES)
            SchemaUtils.create(*TABLES)
        }
        return SqlUnitOfWork(db)
    }
}
